create table accounting_payables(id bigint generated by default as identity primary key,tenant_id bigint not null references tenants(id),company_id bigint not null references companies(id),branch_id bigint not null references branches(id),supplier_id bigint not null references suppliers(id),supplier_invoice_id bigint not null,idempotency_key varchar(160) not null,amount numeric(18,2) not null,currency varchar(3) not null,posted_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,supplier_invoice_id));
